########## dashboard/src/reducer.ts
     1	// Pure reducer: folds WS messages into dashboard state. No React, no I/O —
     2	// so it is unit-testable in isolation (see reducer.test.ts).
     3	
     4	import type { DashState, LiveEvent, NodeState, TimelineLine, WsMessage } from "./types";
     5	
     6	export const initialState: DashState = {
     7	  nodes: {},
     8	  counters: { active_nodes: 0, threats_detected: 0, filters_deployed: 0, frames_blocked: 0 },
     9	  timeline: [],
    10	  stage: "idle",
    11	  activeNode: null,
    12	  activeAttack: null,
    13	  seq: 0,
    14	};
    15	
    16	const STAGE_BY_TYPE: Partial<Record<LiveEvent["type"], DashState["stage"]>> = {
    17	  ANOMALY_DETECTED: "trigger",
    18	  AGENT_ANALYZING: "agent",
    19	  VERIFYING: "verify",
    20	  OTA_DEPLOYING: "ota",
    21	  DEPLOYED: "done",
    22	};
    23	
    24	function describe(e: LiveEvent): { text: string; tone: TimelineLine["tone"] } {
    25	  const p = e.payload;
    26	  const node = e.node_id ?? "—";
    27	  switch (e.type) {
    28	    case "NODE_UP":
    29	      return { text: `${node} online`, tone: "info" };
    30	    case "NODE_DOWN":
    31	      return { text: `${node} went offline`, tone: "bad" };
    32	    case "ANOMALY_DETECTED":
    33	      return { text: `${node} anomaly — ${p.count ?? "?"} frames in window`, tone: "warn" };
    34	    case "AGENT_ANALYZING":
    35	      return { text: `${node} agent analyzing (attempt ${p.attempt ?? 1})`, tone: "info" };
    36	    case "FILTER_GENERATED":
    37	      return { text: `${node} filter generated — ${p.attack_class ?? "?"}`, tone: "info" };
    38	    case "VERIFYING":
    39	      return { text: `${node} verifying filter (replay test)`, tone: "info" };
    40	    case "VERIFY_FAILED":
    41	      return { text: `${node} verify FAILED ${p.tests ?? ""} (fpr=${p.fpr ?? "?"})`, tone: "bad" };
    42	    case "VERIFY_PASSED":
    43	      return { text: `${node} verify PASSED ${p.tests ?? ""}`, tone: "ok" };
    44	    case "OTA_DEPLOYING":
    45	      return { text: `${node} deploying filter OTA`, tone: "info" };
    46	    case "DEPLOYED":
    47	      return { text: `${node} PROTECTED — ${p.attack_class ?? "filter"} deployed`, tone: "ok" };
    48	    case "FRAME_BLOCKED":
    49	      return { text: `${node} blocked ${p.count ?? 1} attack frames`, tone: "ok" };
    50	    default:
    51	      return { text: e.type, tone: "info" };
    52	  }
    53	}
    54	
    55	function setNodeState(state: DashState, nodeId: string | null, ns: NodeState): DashState["nodes"] {
    56	  if (!nodeId || !state.nodes[nodeId]) return state.nodes;
    57	  return { ...state.nodes, [nodeId]: { ...state.nodes[nodeId], state: ns } };
    58	}
    59	
    60	export function reduce(state: DashState, msg: WsMessage): DashState {
    61	  if (msg.type === "SNAPSHOT") {
    62	    const nodes: DashState["nodes"] = {};
    63	    for (const n of msg.payload.nodes) nodes[n.node_id] = n;
    64	    return { ...state, nodes, counters: msg.payload.counters };
    65	  }
    66	
    67	  const e = msg;
    68	  let nodes = state.nodes;
    69	  const counters = { ...state.counters };
    70	  let activeNode = state.activeNode;
    71	  let activeAttack = state.activeAttack;
    72	
    73	  switch (e.type) {
    74	    case "NODE_UP":
    75	      if (e.node_id && !nodes[e.node_id]) {
    76	        nodes = {
    77	          ...nodes,
    78	          [e.node_id]: {
    79	            node_id: e.node_id,
    80	            state: "NORMAL",
    81	            last_seen: e.ts,
    82	            fw_version: "v1",
    83	            label: e.node_id,
    84	            blocked: 0,
    85	          },
    86	        };
    87	      }
    88	      break;
    89	    case "NODE_DOWN":
    90	      nodes = setNodeState(state, e.node_id, "OFFLINE");
    91	      break;
    92	    case "ANOMALY_DETECTED":
    93	      nodes = setNodeState(state, e.node_id, "ALERT");
    94	      counters.threats_detected += 1;
    95	      activeNode = e.node_id;
    96	      break;
    97	    case "FILTER_GENERATED":
    98	      activeAttack = (e.payload.attack_class as string) ?? activeAttack;
    99	      break;
   100	    case "OTA_DEPLOYING":
   101	      nodes = setNodeState(state, e.node_id, "UPDATING");
   102	      break;
   103	    case "DEPLOYED":
   104	      nodes = setNodeState(state, e.node_id, "PROTECTED");
   105	      counters.filters_deployed += 1;
   106	      break;
   107	    case "FRAME_BLOCKED": {
   108	      const c = Number(e.payload.count ?? 1);
   109	      counters.frames_blocked += c;
   110	      if (e.node_id && nodes[e.node_id]) {
   111	        nodes = {
   112	          ...nodes,
   113	          [e.node_id]: { ...nodes[e.node_id], blocked: nodes[e.node_id].blocked + c },
   114	        };
   115	      }
   116	      break;
   117	    }
   118	    default:
   119	      break;
   120	  }
   121	
   122	  counters.active_nodes = Object.values(nodes).filter((n) => n.state !== "OFFLINE").length;
   123	
   124	  const stage = STAGE_BY_TYPE[e.type] ?? state.stage;
   125	  const { text, tone } = describe(e);
   126	  const line: TimelineLine = { id: state.seq, ts: e.ts, node_id: e.node_id, type: e.type, text, tone };
   127	  const timeline = [line, ...state.timeline].slice(0, 60);
   128	
   129	  return { ...state, nodes, counters, timeline, stage, activeNode, activeAttack, seq: state.seq + 1 };
   130	}
########## dashboard/src/dashboardView.ts
     1	import type { Stage, TimelineLine } from "./types";
     2	
     3	export function selectFrameFeed(timeline: TimelineLine[], limit: number): TimelineLine[] {
     4	  return timeline.slice(0, Math.max(0, limit));
     5	}
     6	
     7	export function selectLatestAnomaly(timeline: TimelineLine[]): TimelineLine | undefined {
     8	  return timeline.find((line) => line.type === "ANOMALY_DETECTED");
     9	}
    10	
    11	export interface WorkflowView {
    12	  detectorActive: boolean;
    13	  devinActive: boolean;
    14	  retryActive: boolean;
    15	  devinStatus: string;
    16	}
    17	
    18	export function getWorkflowView(stage: Stage, attack: string | null): WorkflowView {
    19	  return {
    20	    detectorActive: stage === "trigger",
    21	    devinActive: stage === "agent" || stage === "verify" || stage === "ota",
    22	    retryActive: Boolean(attack) && (stage === "agent" || stage === "verify"),
    23	    devinStatus:
    24	      stage === "verify"
    25	        ? "Running oracle replay"
    26	        : stage === "ota"
    27	          ? "Deploying verified policy"
    28	          : stage === "agent"
    29	            ? `Generating ${attack ?? "new filter"}`
    30	            : "Ready for anomaly context",
    31	  };
    32	}
########## dashboard/src/useLive.ts
     1	import { useEffect, useReducer, useState } from "react";
     2	
     3	import { initialState, reduce } from "./reducer";
     4	import type { WsMessage } from "./types";
     5	
     6	const WS_URL = import.meta.env.VITE_WS_URL ?? "ws://localhost:8000/live";
     7	
     8	export function useLive() {
     9	  const [state, dispatch] = useReducer(reduce, initialState);
    10	  const [connected, setConnected] = useState(false);
    11	
    12	  useEffect(() => {
    13	    let ws: WebSocket;
    14	    let retry: ReturnType<typeof setTimeout>;
    15	    let closed = false;
    16	
    17	    const connect = () => {
    18	      ws = new WebSocket(WS_URL);
    19	      ws.onopen = () => setConnected(true);
    20	      ws.onclose = () => {
    21	        setConnected(false);
    22	        if (!closed) retry = setTimeout(connect, 1000);
    23	      };
    24	      ws.onmessage = (msg) => {
    25	        try {
    26	          dispatch(JSON.parse(msg.data) as WsMessage);
    27	        } catch {
    28	          // ignore malformed frames
    29	        }
    30	      };
    31	    };
    32	    connect();
    33	
    34	    return () => {
    35	      closed = true;
    36	      clearTimeout(retry);
    37	      ws?.close();
    38	    };
    39	  }, []);
    40	
    41	  return { state, connected };
    42	}

