     1	import type { Stage, TimelineLine } from "./types";
     2	
     3	export function selectFrameFeed(timeline: TimelineLine[], limit: number): TimelineLine[] {
     4	  return timeline.slice(0, Math.max(0, limit));
     5	}
     6	
     7	export function selectLatestAnomaly(timeline: TimelineLine[]): TimelineLine | undefined {
     8	  return timeline.find((line) => line.type === "ANOMALY_DETECTED");
     9	}
    10	
    11	export interface WorkflowView {
    12	  detectorActive: boolean;
    13	  devinActive: boolean;
    14	  retryActive: boolean;
    15	  devinStatus: string;
    16	}
    17	
    18	export function getWorkflowView(stage: Stage, attack: string | null): WorkflowView {
    19	  return {
    20	    detectorActive: stage === "trigger",
    21	    devinActive: stage === "agent" || stage === "verify" || stage === "ota",
    22	    retryActive: Boolean(attack) && (stage === "agent" || stage === "verify"),
    23	    devinStatus:
    24	      stage === "verify"
    25	        ? "Running oracle replay"
    26	        : stage === "ota"
    27	          ? "Deploying verified policy"
    28	          : stage === "agent"
    29	            ? `Generating ${attack ?? "new filter"}`
    30	            : "Ready for anomaly context",
    31	  };
    32	}
########## dashboard/src/useLive.ts
     1	import { useEffect, useReducer, useState } from "react";
     2	
     3	import { initialState, reduce } from "./reducer";
     4	import type { WsMessage } from "./types";
     5	
     6	const WS_URL = import.meta.env.VITE_WS_URL ?? "ws://localhost:8000/live";
     7	
     8	export function useLive() {
     9	  const [state, dispatch] = useReducer(reduce, initialState);
    10	  const [connected, setConnected] = useState(false);
    11	
    12	  useEffect(() => {
    13	    let ws: WebSocket;
    14	    let retry: ReturnType<typeof setTimeout>;
    15	    let closed = false;
    16	
    17	    const connect = () => {
    18	      ws = new WebSocket(WS_URL);
    19	      ws.onopen = () => setConnected(true);
    20	      ws.onclose = () => {
    21	        setConnected(false);
    22	        if (!closed) retry = setTimeout(connect, 1000);
    23	      };
    24	      ws.onmessage = (msg) => {
    25	        try {
    26	          dispatch(JSON.parse(msg.data) as WsMessage);
    27	        } catch {
    28	          // ignore malformed frames
    29	        }
    30	      };
    31	    };
    32	    connect();
    33	
    34	    return () => {
    35	      closed = true;
    36	      clearTimeout(retry);
    37	      ws?.close();
    38	    };
    39	  }, []);
    40	
    41	  return { state, connected };
    42	}

