:root {
  --ink: #090b09;
  --surface: #151815;
  --line: rgba(239, 244, 236, 0.1);
  --line-strong: rgba(239, 244, 236, 0.2);
  --text: #f1f4ef;
  --muted: #949c91;
  --acid: #7ddb6a;
  --acid-ink: #0b1609;
  --amber: #d2a25a;
  --red: #d36c64;
  --cyan: #65a69c;
  --radius: 12px;
}

* {
  box-sizing: border-box;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  color: inherit;
}

.dashboard-shell {
  position: relative;
  width: 100vw;
  height: 100dvh;
  min-height: 600px;
  overflow: hidden;
  display: grid;
  grid-template-rows: 70px minmax(0, 1fr);
  color: var(--text);
  background: linear-gradient(145deg, #101310, var(--ink) 58%);
  isolation: isolate;
}

.dashboard-shell::before {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  opacity: 0.06;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.28'/%3E%3C/svg%3E");
  content: "";
}

.topbar {
  min-width: 0;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 24px;
  padding: 0 22px;
  border-bottom: 1px solid var(--line);
  background: rgba(9, 11, 9, 0.9);
  backdrop-filter: blur(22px);
}

.wordmark {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 15px;
  font-weight: 640;
  letter-spacing: -0.02em;
}

.wordmark-mark {
  position: relative;
  width: 29px;
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--acid);
  box-shadow: none;
}

.wordmark-mark::before,
.wordmark-mark::after,
.wordmark-mark span {
  position: absolute;
  height: 1px;
  background: var(--acid-ink);
  content: "";
}

.wordmark-mark::before {
  width: 15px;
  transform: rotate(45deg);
}

.wordmark-mark::after {
  width: 15px;
  transform: rotate(-45deg);
}

.wordmark-mark span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.wordmark-edition {
  padding-left: 10px;
  border-left: 1px solid var(--line-strong);
  color: var(--muted);
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.14em;
}

