input.content:
/* Panel styling follows ISA-101 HMI convention: a low-saturation grey control
   face where colour is spent only on state. An amber lamp means something is
   wrong; nothing decorative is allowed to use the alarm palette. */

:root {
  --panel: #c4c2bb;
  --panel-hi: #d3d1ca;
  --panel-lo: #b0aea7;
  --recess: #a8a6a0;
  --paper: #e7e5de;

  --ink: #191b19;
  --ink-mid: #4e514d;
  --ink-low: #5f625d;
  --engrave: #8b8981;
  --engrave-hi: #dad8d1;

  --lens: #6d6b66;
  --alarm: #a82a17;
  --amber: #b8791a;
  --amber-ink: #7d5210;
  --ok: #256b47;
  --busy: #1d4c76;

  --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, "DejaVu Sans Mono", Consolas, monospace;
  --note-face: Georgia, "Times New Roman", serif;

  --gap: 10px;
}

* {
  box-sizing: border-box;
}

:focus-visible {
  outline: 2px solid var(--busy);
  outline-offset: 1px;
}

/* --- shell ------------------------------------------------------------- */

.hmi {
  height: 100dvh;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  color: var(--ink);
  background-color: var(--panel);
  /* Brushed anodised face. Barely visible; it stops the grey reading as flat. */
  background-image: repeating-linear-gradient(
    90deg,
    rgba(255, 255, 255, 0.035) 0 1px,
    rgba(0, 0, 0, 0.02) 1px 3px
  );
}

/* --- header rail ------------------------------------------------------- */

.rail {
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  gap: 24px;
  padding: 0 var(--gap);
  border-bottom: 1px solid var(--engrave);
  box-shadow: inset 0 -1px 0 var(--engrave-hi);
}

.nameplate {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 14px;
  margin: 8px 0;
  background: linear-gradient(var(--panel-hi), var(--panel-lo));
  border: 1px solid var(--engrave);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5);
}

.screw {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, var(--panel-hi), var(--lens));
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.35);
}

.nameplate-text {
  display: grid;
  gap: 1px;
  padding: 7px 0;
}

.nameplate-text strong {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-transform: uppercase;
}

.nameplate-text small,
.legend-note,
.gauge-label,
.well-tag,
.loop-owner,
.link-text small {
  color: var(--ink-mid);
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.gauges {
  display: flex;
  align-items: center;
  gap: 1px;
}

.gauge {
  display: grid;
  gap: 2px;
  justify-items: center;
  min-width: 104px;
  padding: 9px 12px;
  background: var(--recess);
  box-shadow:
    inset 1px 1px 0 rgba(0, 0, 0, 0.18),
    inset -1px -1px 0 rgba(255, 255, 255, 0.24);
}

.gauge-value {
  font-size: 19px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.link {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 12px 0 10px;
  margin: 8px 0;
  border: 1px solid var(--engrave);
  background: var(--panel-lo);
}

.link-text {
  display: grid;
  gap: 1px;
}

.link-text strong {
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.link:not([data-linked]) .link-text strong {
  color: var(--alarm);
}

/* --- annunciator lamps ------------------------------------------------- */

.lamp {
  flex: none;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--lens);
  box-shadow:
    inset 0 0 0 1px rgba(0, 0, 0, 0.45),
    inset 1px 1px 1px rgba(255, 255, 255, 0.3);
}

.lamp[data-tone="alarm"] {
  background: var(--amber);
}

.lamp[data-tone="ok"] {
  background: var(--ok);
}

.lamp[data-tone="busy"] {
  background: var(--busy);
}

.lamp[data-tone="dead"] {
  background: #8f8d87;
}

/* Unacknowledged alarms blink — the convention, not an effect. */
.lamp[data-blink] {
  animation: annunciator 1s steps(1, end) infinite;
}

@keyframes annunciator {
  0%,
  49% {
    background: var(--alarm);
  }
  50%,
  100% {
