  min-height: 0;
}

.bay {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 0 11px 11px;
  background: var(--panel);
  border: 1px solid var(--engrave);
  box-shadow:
    inset 1px 1px 0 rgba(255, 255, 255, 0.42),
    inset -1px -1px 0 rgba(0, 0, 0, 0.14);
}

.bay-fleet {
  grid-column: 1;
  grid-row: 1 / span 2;
}

.bay-capture {
  grid-column: 2;
  grid-row: 1;
}

.bay-filter {
  grid-column: 2;
  grid-row: 2;
}

.bay-log {
  grid-column: 3;
  grid-row: 1 / span 2;
}

.legend {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin: 0 -11px 10px;
  padding: 8px 11px;
  border-bottom: 1px solid var(--engrave);
  box-shadow: inset 0 -2px 0 var(--engrave-hi);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.legend-note {
  margin-left: auto;
  font-weight: 400;
}

.empty {
  margin: 0;
  padding: 14px 0;
  color: var(--ink-mid);
  font-size: 11px;
  line-height: 1.6;
}

/* --- fleet ------------------------------------------------------------- */

.fleet-list {
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-y: auto;
  min-height: 0;
}

.fleet-row {
  display: grid;
  grid-template-columns: 11px 1fr auto;
  align-items: center;
  gap: 4px 8px;
  padding: 8px 8px 8px 7px;
  border-bottom: 1px solid rgba(139, 137, 129, 0.45);
}

.fleet-row[data-focus] {
  background: var(--recess);
  box-shadow: inset 2px 0 0 var(--amber);
}

.fleet-id {
  font-size: 13px;
  font-weight: 600;
}

.fleet-state {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-mid);
}

.fleet-row[data-state="alert"] .fleet-state {
  color: var(--amber-ink);
  font-weight: 700;
}

.fleet-row[data-state="protected"] .fleet-state {
  color: var(--ok);
}

.fleet-row[data-state="updating"] .fleet-state {
  color: var(--busy);
}

.fleet-row[data-state="offline"] {
  color: var(--ink-low);
}

.fleet-meta {
  grid-column: 2 / -1;
  display: flex;
  gap: 12px;
  font-size: 10px;
  color: var(--ink-mid);
}

