.readout {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 1px;
  margin: 0 0 var(--gap);
}

.readout > div {
  display: grid;
  gap: 3px;
  padding: 8px 10px;
  background: var(--recess);
  box-shadow:
    inset 1px 1px 0 rgba(0, 0, 0, 0.16),
    inset -1px -1px 0 rgba(255, 255, 255, 0.22);
}

.readout dt {
  color: var(--ink-mid);
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.readout dd {
