}

.well-tag {
  position: absolute;
  top: 4px;
  left: 10px;
}

.well-hex ol {
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-y: auto;
  max-height: 74px;
  font-size: 11px;
  line-height: 1.7;
  word-break: break-all;
}

.well-hex em {
  margin-right: 9px;
  color: var(--ink-low);
  font-style: normal;
}

