.note {
  margin: 0 0 var(--gap);
  padding-left: 9px;
  border-left: 2px solid var(--engrave);
  color: var(--ink-mid);
  font-family: var(--note-face);
  font-size: 13px;
  font-style: italic;
  line-height: 1.5;
}

.verdict {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  margin-top: var(--gap);
  padding: 9px 11px;
  background: var(--panel-lo);
  border-top: 1px solid var(--engrave);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.4);
}

.verdict-wait,
.verdict-figures dt {
  color: var(--ink-mid);
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.verdict-figures {
  display: flex;
  gap: 22px;
  margin: 0;
}

.verdict-figures div {
  display: grid;
  gap: 2px;
}

.verdict-figures dd {
  margin: 0;
  font-size: 17px;
  font-weight: 600;
}

/* The signature: the oracle's verdict pressed onto the sheet. */
.stamp {
  margin-left: auto;
  padding: 3px 12px;
  color: var(--alarm);
  border: 2px double currentcolor;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  transform: rotate(-8deg);
  mix-blend-mode: multiply;
  opacity: 0.86;
}

.stamp[data-passed] {
  color: var(--ok);
}

.verdict-log {
  flex-basis: 100%;
  order: 9;
  margin: 4px 0 0;
  max-height: 62px;
  overflow: auto;
  color: var(--ink-mid);
  font-size: 10.5px;
  line-height: 1.55;
  white-space: pre-wrap;
}

.attempts {
  margin: var(--gap) 0 0;
  padding: 0;
  list-style: none;
  font-size: 10px;
}

.attempts li {
  display: grid;
  grid-template-columns: 1fr auto 54px;
  gap: 10px;
  padding: 5px 0;
  border-top: 1px solid rgba(139, 137, 129, 0.45);
  color: var(--alarm);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.attempts li[data-passed] {
  color: var(--ok);
}

.attempts li span:first-child {
  color: var(--ink-mid);
}

.attempts li span:last-child {
  text-align: right;
  font-weight: 700;
}

/* --- event log -------------------------------------------------------- */

.log {
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-y: auto;
  min-height: 0;
}

.log-row {
  display: grid;
  grid-template-columns: auto 52px 1fr;
  gap: 9px;
  padding: 5px 4px;
  border-bottom: 1px solid rgba(139, 137, 129, 0.4);
  font-size: 11px;
  line-height: 1.45;
}

.log-row time {
  color: var(--ink-low);
}

.log-kind {
  color: var(--ink-mid);
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding-top: 1px;
}

.log-row[data-tone="warn"] .log-kind {
  color: var(--amber-ink);
  font-weight: 700;
}

.log-row[data-tone="bad"] .log-kind {
  color: var(--alarm);
  font-weight: 700;
}

.log-row[data-tone="ok"] .log-kind {
  color: var(--ok);
}

/* --- narrower panels -------------------------------------------------- */

@media (max-width: 1240px) {
  .bays {
    grid-template-columns: 260px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
  }

  .bay-fleet {
    grid-row: 1 / span 3;
  }

  .bay-log {
    grid-column: 2;
    grid-row: 3;
    max-height: 190px;
  }
}

@media (max-width: 860px) {
  .hmi {
    height: auto;
    min-height: 100dvh;
  }

  .rail {
    flex-wrap: wrap;
    gap: 8px 16px;
  }

  .gauges {
    flex-wrap: wrap;
  }

  .bays {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: none;
  }

  .bay {
    grid-column: 1 !important;
    grid-row: auto !important;
    max-height: none;
  }

  .fleet-list,
  .log {
    overflow: visible;
  }
}

@media (prefers-reduced-motion: reduce) {
  .lamp[data-blink] {
    animation: none;
  }

  .lamp[data-blink] {
    background: var(--alarm);
  }
}

