  letter-spacing: -0.03em;
}

.wordmark small,
.panel-head span,
.eyebrow,
.evidence-tag,
.code-tag,
.rail-owner,
.counters span,
.verdict dt,
.verdict-pending {
  color: var(--faint);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.counters {
  display: flex;
  gap: 34px;
  margin-left: auto;
}

.counters div {
  display: grid;
  gap: 2px;
  justify-items: end;
}

.counters strong {
  font-family: var(--mono);
  font-size: 17px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.link-pill {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 12px 5px 10px;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  color: var(--dim);
  font-size: 11px;
  letter-spacing: 0.06em;
}

.link-pill i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--crimson);
}

.link-pill[data-linked] i {
  background: var(--jade);
  box-shadow: 0 0 0 3px rgba(69, 185, 141, 0.16);
}

/* --- stage ------------------------------------------------------------- */

.stage {
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr) 340px;
  gap: var(--gap);
  padding: var(--gap) 26px 26px;
  min-height: 0;
}

.lane {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-height: 0;
}

.panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 15px 16px 16px;
  background: var(--raise);
  border: 1px solid var(--line);
  border-radius: 10px;
}

.panel-head {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 13px;
}

.panel-head h2 {
  margin: 0;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.panel-head span {
  margin-left: auto;
  text-align: right;
}

.blank {
  margin: 0;
  max-width: 46ch;
  color: var(--faint);
  font-size: 12.5px;
  line-height: 1.65;
}

/* --- fleet ------------------------------------------------------------- */

.fleet {
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-y: auto;
  min-height: 0;
}

.node {
  display: grid;
  grid-template-columns: 7px 1fr auto;
  align-items: center;
  gap: 3px 10px;
  padding: 11px 2px;
  border-bottom: 1px solid var(--line);
}

.node:last-child {
  border-bottom: 0;
}

.node-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--faint);
}

.node[data-state="alert"] .node-dot {
  background: var(--ember);
  box-shadow: 0 0 0 3px var(--ember-dim);
}

.node[data-state="protected"] .node-dot {
  background: var(--jade);
}

.node[data-state="updating"] .node-dot {
  background: var(--steel);
}

.node[data-state="offline"] .node-dot {
  background: #33373f;
}

.node-id {
  font-family: var(--mono);
  font-size: 13px;
  letter-spacing: -0.02em;
}

.node-state {
  color: var(--faint);
  font-size: 10px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.node[data-state="alert"] .node-state {
  color: var(--ember);
}

.node[data-state="protected"] .node-state {
  color: var(--jade);
}

.node[data-state="updating"] .node-state {
  color: var(--steel);
}

.node[data-focus] .node-id {
  color: var(--ember);
}

.node-meta {
  grid-column: 2 / -1;
  color: var(--faint);
  font-family: var(--mono);
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
}

.node[data-state="offline"] {
  opacity: 0.45;
}

/* --- capture: the headline -------------------------------------------- */

.capture {
  padding: 4px 2px 0;
}

.eyebrow {
  display: block;
  margin-bottom: 12px;
}

.eyebrow time {
  font-family: var(--mono);
}

.capture h1 {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(34px, 4.4vw, 58px);
  font-weight: 400;
  line-height: 0.98;
  letter-spacing: -0.015em;
  text-transform: lowercase;
}

.dek {
  margin: 14px 0 0;
  max-width: 52ch;
  color: var(--dim);
  font-size: 13.5px;
  line-height: 1.6;
}

.facts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 38px;
  margin: 20px 0 0;
}

.facts div {
  display: grid;
  gap: 3px;
}

.facts dt {
  color: var(--faint);
  font-size: 10px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.facts dd {
  margin: 0;
  font-family: var(--mono);
  font-size: 14px;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.evidence {
  margin-top: 18px;
  padding-top: 13px;
  border-top: 1px solid var(--line);
}

.evidence ol {
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
  color: var(--faint);
  font-family: var(--mono);
  font-size: 10.5px;
  line-height: 1.85;
  word-break: break-all;
}

/* --- loop rail -------------------------------------------------------- */

.rail {
  position: relative;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  margin: 0;
  padding: 0;
  list-style: none;
}

/* One hairline through every step; the dots sit on it. */
.rail::before {
  position: absolute;
  top: 3px;
  left: 10%;
  right: 10%;
  height: 1px;
  background: var(--line-2);
  content: "";
}

.rail-step {
  display: grid;
  justify-items: center;
  gap: 8px;
}

.rail-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #2a2e36;
  outline: 4px solid var(--ground);
  transition:
    background 180ms ease,
    box-shadow 180ms ease;
}

.rail-step[data-phase="past"] .rail-dot {
  background: var(--jade);
}

.rail-step[data-phase="active"] .rail-dot {
  background: var(--ember);
  box-shadow: 0 0 0 4px var(--ember-dim);
}

.rail-label {
  color: var(--faint);
  font-size: 11.5px;
  font-weight: 500;
  letter-spacing: 0.01em;
}

.rail-step[data-phase="active"] .rail-label {
  color: var(--text);
}

.rail-step[data-phase="past"] .rail-label {
  color: var(--dim);
}

.rail-owner {
  margin-top: -4px;
}

/* --- generated filter: the hero --------------------------------------- */

.panel-filter {
  flex: 1;
  min-height: 0;
}

.rationale {
  margin: 0 0 14px;
  max-width: 74ch;
  color: var(--dim);
  font-family: var(--serif);
  font-size: 15px;
  font-style: italic;
  line-height: 1.5;
}

.code-wrap {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 26px 0 0;
  background: var(--sunk);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.code-tag {
  position: absolute;
  top: 9px;
  left: 16px;
  font-family: var(--mono);
}

.code {
  display: flex;
  flex-direction: column;
  overflow: auto;
  min-height: 0;
  padding: 0 16px 14px;
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.75;
  tab-size: 4;
  white-space: pre;
}

.code-line[data-kind="comment"] {
  color: #4a505c;
}

.code-line[data-kind="pre"] {
  color: var(--steel);
  opacity: 0.65;
}

.code-line[data-kind="code"] {
  color: #dfe4ee;
}

/* --- verdict ---------------------------------------------------------- */

.verdict {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px 40px;
  margin-top: 15px;
}

.verdict dl {
  display: flex;
  gap: 34px;
  margin: 0;
}

.verdict dl div {
  display: grid;
  gap: 3px;
}

.verdict dd {
  margin: 0;
  font-family: var(--mono);
  font-size: 18px;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.03em;
}

.badge {
  margin-left: auto;
  padding: 6px 16px;
  border: 1px solid currentcolor;
  border-radius: 999px;
  color: var(--crimson);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.verdict[data-passed] .badge {
  color: var(--jade);
  box-shadow: 0 0 22px rgba(69, 185, 141, 0.12);
}

.verdict-log {
  flex-basis: 100%;
  order: 9;
  margin: 0;
  max-height: 58px;
  overflow: auto;
  color: var(--faint);
  font-family: var(--mono);
  font-size: 10.5px;
  line-height: 1.6;
  white-space: pre-wrap;
}

.attempts {
  margin: 16px 0 0;
  padding: 14px 0 0;
  border-top: 1px solid var(--line);
  list-style: none;
  font-family: var(--mono);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.attempts li {
  display: grid;
  grid-template-columns: 1fr auto 46px;
  gap: 14px;
  padding: 4px 0;
  color: var(--crimson);
}

.attempts li[data-passed] {
  color: var(--jade);
}

.attempts li span:first-child {
  color: var(--faint);
}

.attempts li span:last-child {
  text-align: right;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* --- event log -------------------------------------------------------- */

.log {
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-y: auto;
  min-height: 0;
}

.log-row {
  display: grid;
  grid-template-columns: auto 44px 1fr;
  gap: 10px;
  padding: 7px 0;
  border-bottom: 1px solid var(--line);
  color: var(--dim);
  font-size: 11.5px;
  line-height: 1.5;
}

.log-row time {
  color: var(--faint);
  font-family: var(--mono);
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
}

.log-kind {
  color: var(--faint);
  font-size: 9.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding-top: 1px;
}

.log-row[data-tone="warn"] .log-kind {
  color: var(--ember);
}

.log-row[data-tone="bad"] .log-kind {
  color: var(--crimson);
}

.log-row[data-tone="ok"] .log-kind {
  color: var(--jade);
}

/* --- narrower ---------------------------------------------------------- */

@media (max-width: 1280px) {
  .stage {
    grid-template-columns: 220px minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr) auto;
  }

  .panel-fleet {
    grid-row: 1 / span 2;
  }

  .panel-log {
    grid-column: 2;
    max-height: 200px;
  }
}

@media (max-width: 900px) {
  .shell {
    height: auto;
    min-height: 100dvh;
  }

  .topbar {
    flex-wrap: wrap;
    height: auto;
    padding: 14px 18px;
    gap: 14px 22px;
  }

  .counters {
    gap: 22px;
  }

  .stage {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: none;
    padding: 14px 18px 22px;
  }

  .panel {
    grid-column: 1 !important;
    grid-row: auto !important;
    max-height: none;
  }

  .fleet,
  .log,
  .code {
    overflow: visible;
  }
}

