t = p.read_text()
old = """    const target = lines.findIndex((line) => line.includes("block_frame("));
    const first = box.firstElementChild;
    if (target <= 0 || first === null) {
      box.scrollTop = 0;
      return;
    }
    // Measure a real line rather than dividing scrollHeight, which includes
    // padding and lands the scroll halfway through a row.
    const lineHeight = first.getBoundingClientRect().height;
    const inView = (target + 1) * lineHeight <= box.clientHeight;
    box.scrollTop = inView ? 0 : Math.round((target - 1) * lineHeight);
"""
new = """    const rows = box.children;
    const target = lines.findIndex((line) => line.includes("block_frame("));
    if (target <= 0 || rows.length <= target) {
      box.scrollTop = 0;
      return;
    }
    // Offsets off the rendered rows, not arithmetic on scrollHeight — padding
    // and fractional line boxes otherwise land the scroll mid-row.
    const top = (element: Element): number => (element as HTMLElement).offsetTop;
    const reach = top(rows[target]) - top(rows[0]) + (top(rows[target + 1] ?? rows[target]) - top(rows[target]));
    box.scrollTop = reach <= box.clientHeight ? 0 : top(rows[target - 1]) - top(rows[0]);
"""
assert t.count(old) == 1
